function solve(args) {
  const s = args[0];
  let depth = 0;
  let maxDepth = 0;
  let pairs = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '[') {
      depth++;
      if (depth > maxDepth) maxDepth = depth;
    } else if (s[i] === ']') {
      if (depth > 0) {
        depth--;
        pairs++;
      }
    }
  }
  return maxDepth >= 2 && pairs >= 2;
}

