function solve(args) {
  const grid = args[0];
  const k = args[1];
  const n = grid.length;
  const dirs = [[-1,0],[1,0],[0,-1],[0,1]];

  function neighbors(r, c) {
    const res = [];
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < n && nc >= 0 && nc < n) res.push([nr, nc]);
    }
    return res;
  }

  function canReach(startR, startC, steps) {
    const visited = new Set();
    let frontier = [[startR, startC]];
    visited.add(startR * n + startC);
    for (let s = 0; s < steps; s++) {
      const next = [];
      for (const [r, c] of frontier) {
        for (const [nr, nc] of neighbors(r, c)) {
          const key = nr * n + nc;
          if (!visited.has(key)) {
            visited.add(key);
            next.push([nr, nc]);
          }
        }
      }
      if (next.length === 0) return false;
      frontier = next;
    }
    return true;
  }

  const result = [];
  let curR = -1, curC = -1;

  for (let pos = 0; pos < k; pos++) {
    const remaining = k - pos - 1;
    let best = null;
    let bestR = -1, bestC = -1;

    if (pos === 0) {
      for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
          const v = grid[r][c];
          if (best === null || v < best) {
            if (canReach(r, c, remaining)) {
              best = v;
              bestR = r;
              bestC = c;
            }
          }
        }
      }
    } else {
      for (const [nr, nc] of neighbors(curR, curC)) {
        const v = grid[nr][nc];
        if (best === null || v < best) {
          if (canReach(nr, nc, remaining)) {
            best = v;
            bestR = nr;
            bestC = nc;
          }
        }
      }
    }

    result.push(best);
    curR = bestR;
    curC = bestC;
  }

  return result;
}

