function solve(args) {
  const grid = args[0];
  const k = args[1];
  const n = grid.length;
  const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
  const INF = Infinity;

  const best = new Array(n * n).fill(INF);
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      best[r * n + c] = grid[r][c];
    }
  }

  const result = [];
  let current = best.slice();

  for (let step = 0; step < k; step++) {
    let minVal = INF;
    for (let i = 0; i < current.length; i++) {
      if (current[i] < minVal) minVal = current[i];
    }
    result.push(minVal);

    if (step === k - 1) break;

    const next = new Array(n * n).fill(INF);
    for (let r = 0; r < n; r++) {
      for (let c = 0; c < n; c++) {
        const idx = r * n + c;
        if (current[idx] === minVal) {
          for (const [dr, dc] of dirs) {
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
              const nidx = nr * n + nc;
              if (grid[nr][nc] < next[nidx]) next[nidx] = grid[nr][nc];
            }
          }
        }
      }
    }
    current = next;
  }

  return result;
}

