  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      cells.push([grid[r][c], r, c]);
    }
  }
  cells.sort((a, b) => a[0] - b[0]);
  const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  const best = new Array(k);
  for (let i = 0; i < k; i++) best[i] = Infinity;
  const reach = [];
  for (let i = 0; i < k; i++) reach.push(new Set());
  for (const [val, r, c] of cells) {
    if (val > best[0]) break;
    const cur = new Array(k);
    cur[0] = val;
    for (let step = 1; step < k; step++) {
      let m = Infinity;
      for (const [dr, dc] of dirs) {
        const nr = r + dr, nc = c + dc;
        if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
          const key = nr * n + nc;
          if (reach[step - 1].has(key)) {
            const v = grid[nr][nc];
            if (v < m) m = v;
          }
        }
      }
      cur[step] = m;
    }
    let better = false;
    for (let step = 0; step < k; step++) {
      if (cur[step] < best[step]) { better = true; break; }
      if (cur[step] > best[step]) break;
    }
    if (better) {
      for (let step = 0; step < k; step++) best[step] = cur[step];
    }
